std::vector<int> nextGreater(const std::vector<int>& nums) {
    std::vector<int> result(nums.size(), -1);
    std::stack<int> s;  // indices, values decreasing
    for (int i = 0; i < (int)nums.size(); ++i) {
        while (!s.empty() && nums[s.top()] < nums[i]) {
            result[s.top()] = nums[i];
            s.pop();
        }
        s.push(i);
    }
    return result;
}

